    "normalized_key": "lseg:associatecontentanalystgermanlanguagespecialist:bangalore",
    "title": "Associate Content Analyst - German Language Specialist",
    "company": "LSEG",
    "location_raw": "IND-Bangalore-A, RMZ Infinity",
